"""Campaign record adapter and revision ledger.

A capture record is a typed row of the version 3 campaign wire format.  The
identity of a record is ``(type,id)`` and is global across captures, so the
ledger reconciles publication times and revisions before any census work.
"""

from common import (COLUMNS,ID,MAX_ATTEMPT,MAX_PAYLOAD,MAX_REVISION,MAX_TIME,
                    Invalid,address,decimal,decode64)

# Record layout: (type,id,revision,published,op,lease,event,probe,target,
#                  responder,result,service,attempt,payload)
TYPE,IDENT,REVISION,PUBLISHED,OP,LEASE,EVENT,PROBE,TARGET,RESPONDER,RESULT,SERVICE,ATTEMPT,PAYLOAD=range(14)

DELETE_CONTENT=('delete',)


def content(record):
    """Semantic content of a record, ignoring publication time and spelling."""
    if record[OP]=='delete':
        return DELETE_CONTENT
    return ('put',record[LEASE],record[EVENT],record[PROBE],record[TARGET],
            record[RESPONDER],record[RESULT],record[SERVICE],record[ATTEMPT],
            record[PAYLOAD])


def parse_record(values,context,lookup):
    """Parse one logical data record into a typed record.

    Raises ``Invalid`` for any logical record failure; the caller reports the
    record index and keeps the rest of the capture.
    """
    if len(values)!=len(COLUMNS):
        raise Invalid('field count')
    kind,ident,revision_text,published_text,op=values[:5]
    lease,event_text,probe,target_text,responder_text,result,service,attempt_text,payload_text=values[5:]
    if kind not in ('icmp','app'):
        raise Invalid('record type')
    if not isinstance(ident,str) or ID.fullmatch(ident) is None:
        raise Invalid('record id')
    revision=decimal(revision_text,MAX_REVISION)
    published=decimal(published_text,MAX_TIME)
    if op=='delete':
        if any(values[5:]):
            raise Invalid('delete body')
        return (kind,ident,revision,published,'delete','',None,'',None,None,'','',None,b'')
    if op!='put':
        raise Invalid('record op')
    lease_row=context['leases'].get(lease) if isinstance(lease,str) else None
    if lease_row is None:
        raise Invalid('record lease')
    event=decimal(event_text,MAX_TIME)
    if not lease_row['start']<=event<lease_row['end']:
        raise Invalid('record event')
    if event>published:
        raise Invalid('record order')
    target=address(target_text)
    if kind=='icmp':
        if service or attempt_text or payload_text:
            raise Invalid('icmp extras')
        entry=lookup.get((lease,probe))
        if entry is None:
            raise Invalid('icmp probe')
        planned,is_canary=entry
        if planned!=target:
            raise Invalid('icmp target')
        if result not in ('echo','error','timeout'):
            raise Invalid('icmp result')
        if result=='timeout':
            if responder_text:
                raise Invalid('icmp responder')
            responder=None
        else:
            responder=address(responder_text)
        return (kind,ident,revision,published,'put',lease,event,probe,target,
                responder,result,'',None,b'')
    if probe or responder_text:
        raise Invalid('app fields')
    if service not in context['services']:
        raise Invalid('app service')
    attempt=decimal(attempt_text,MAX_ATTEMPT)
    if result not in ('open','closed','timeout'):
        raise Invalid('app result')
    if result in ('closed','timeout'):
        if payload_text:
            raise Invalid('app payload')
        payload=b''
    else:
        payload=decode64(payload_text)
        if len(payload)>MAX_PAYLOAD:
            raise Invalid('app payload size')
        if context['services'][service]=='tcp' and payload:
            raise Invalid('tcp payload')
    return (kind,ident,revision,published,'put',lease,event,'',target,None,
            result,service,attempt,payload)


class Ledger:
    """Publication and revision reconciliation over the captured records."""

    def __init__(self,records):
        self.records=records
        self.groups={}
        for record in records:
            self.groups.setdefault((record[TYPE],record[IDENT]),[]).append(record)

    def at(self,time):
        """Return the live records and the identity counts at a query time."""
        live=[]
        deleted=0
        conflict=0
        for rows in self.groups.values():
            best=None
            for record in rows:
                if record[PUBLISHED]<=time:
                    revision=record[REVISION]
                    if best is None or revision>best:
                        best=revision
            if best is None:
                continue
            contents=set()
            chosen=None
            for record in rows:
                if record[PUBLISHED]<=time and record[REVISION]==best:
                    contents.add(content(record))
                    chosen=record
            if len(contents)>1:
                conflict+=1
            elif chosen[OP]=='delete':
                deleted+=1
            else:
                live.append(chosen)
        counts={'live':len(live),'deleted':deleted,'conflict':conflict}
        return live,counts
PYEOF
